import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  actionTransactionsInternalSchema,
  actionTransactionsSchema,
  type ActionTransactions,
} from "./action-transactions.js";
import { statusDisputesStatusSchema, type StatusDisputesStatus } from "./status-disputes-status.js";

export type ChallengeDisputeResponse = {
  /**
   * A unique identifier that is used to identify and reference an instance of this resource. It is
   * generated by Global Payments to identify the transaction and must be used to action that
   * transaction in future.
   */
  id?: string;
  /** Indicated where the dispute is in the life-cycle. */
  disputeStatus?: StatusDisputesStatus;
  /** Indicates where the document is in its lifecycle. */
  status?: string;
  /** A meaningful label for the document set by Global Payments. */
  documentName?: string;
  /** Information about the Action executed. */
  action?: ActionTransactions;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const challengeDisputeResponseProperties: s.Shape<ChallengeDisputeResponse> = {
  id: s.optional(s.string()),
  disputeStatus: s.optional(s.lazy(() => statusDisputesStatusSchema)),
  status: s.optional(s.string()),
  documentName: s.optional(s.string()),
  action: s.optional(s.lazy(() => actionTransactionsInternalSchema)),
  _keysMap: {
    disputeStatus: "dispute_status",
    documentName: "document_name",
  },
};

export const challengeDisputeResponseInternalSchema: Schema<ChallengeDisputeResponse> =
  s.object<ChallengeDisputeResponse>(challengeDisputeResponseProperties, { additionalProperties: s.json() });

export const challengeDisputeResponseSchema: Schema<ChallengeDisputeResponse> = s.lazySchema(() =>
  s.object<ChallengeDisputeResponse>(
    {
      ...challengeDisputeResponseProperties,
      id: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      action: s.optional(s.lazy(() => actionTransactionsSchema)),
    },
    { additionalProperties: s.json() },
  ),
);
